mapper.select:
SELECT EMPLOYER_NO, BUSINESS_NICKNAME
FROM "EMPLOYER"
WHERE MEMBER_NO = ${memberNo}

SELECT PREFERRED_NO
FROM "PREFERRED"
WHERE PREFERRED_CATEGORY = #{preferredCategory}

SELECT SUPPORT_NO
FROM "SUPPORT"
WHERE SUPPORT_CATEGORY = #{supportCategory}

SELECT COUNT(*)
FROM RECRUITMENT_RESUME
WHERE RECRUITMENT_NO = ${recruitmentNo}
	AND RESUME_NO = ${resumeNo}
